import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/VSCode.html","title":"VSCode","lang":"en-US","frontmatter":{},"git":{"createdTime":1642043880000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":14}]},"readingTime":{"minutes":2.05,"words":614},"filePathRelative":"VSCode.md"}`),a={name:`VSCode.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="vscode" tabindex="-1"><a class="header-anchor" href="#vscode"><span>VSCode</span></a></h1><p>みんな大好きVSCode。<a href="./VisualStudio.html">VisualStudio</a></p><h2 id="キーボードショートカット" tabindex="-1"><a class="header-anchor" href="#キーボードショートカット"><span>キーボードショートカット</span></a></h2><ul><li>C-w ウィンドウ切り替え</li><li>Command+option+shift 矩形選択 <ul><li>WindowsはCtrl+Alt+Shift+矢印</li></ul></li><li>C-u Command+Dのundo（最後の選択を戻す）</li></ul><h2 id="選択範囲が無い時に一行コピーする、をdisableする方法" tabindex="-1"><a class="header-anchor" href="#選択範囲が無い時に一行コピーする、をdisableする方法"><span>選択範囲が無い時に一行コピーする、をdisableする方法</span></a></h2><p>settingで<code>&quot;editor.emptySelectionClipboard&quot;: false</code>相当の事をする。（GUIからemptySeletionで絞り込みしてチェックを外す）</p><h2 id="extensionの作り方" tabindex="-1"><a class="header-anchor" href="#extensionの作り方"><span>extensionの作り方</span></a></h2><p><a href="https://engineering.linecorp.com/ja/blog/uit-enhancement-vscode/" target="_blank" rel="noopener noreferrer">業務で役に立つVS Code機能拡張を作ってみた話 - LINE ENGINEERING</a></p><p><a href="./OilShell.html">OilShell</a>でシンタックスハイライトの作業をしてみたので、関連情報が割とそちらに書いてある。</p><h2 id="watch式でのキャスト" tabindex="-1"><a class="header-anchor" href="#watch式でのキャスト"><span>watch式でのキャスト</span></a></h2><p><code>,c</code>とか足すとその型で見れる。 他にもb, o, xなどがある。</p><h2 id="cpptoolsのキャッシュの削除" tabindex="-1"><a class="header-anchor" href="#cpptoolsのキャッシュの削除"><span>cpptoolsのキャッシュの削除</span></a></h2><p><a href="https://take4-blue.com/program/visual-studio-code%EF%BC%8Dc-c%E6%8B%A1%E5%BC%B5%E3%81%A7%E4%BD%BF%E3%82%8F%E3%82%8C%E3%82%8B%E3%82%AD%E3%83%A3%E3%83%83%E3%82%B7%E3%83%A5%E6%83%85%E5%A0%B1/" target="_blank" rel="noopener noreferrer">Visual Studio Code－C/C++拡張で使われるキャッシュ情報 - Take4-blue</a></p><p>へー、と思って見てみると、Macではパスがだいぶ違っていて後者は見つからなかった。 前者は設定から探してみるとHOMEのLibrary下にあるらしい。へー、こんな所に。 結構大量にたまっていたので消してみた。</p><h2 id="workspaceのみで有効な環境変数" tabindex="-1"><a class="header-anchor" href="#workspaceのみで有効な環境変数"><span>workspaceのみで有効な環境変数</span></a></h2><ul><li><a href="https://kuma-emon.com/it/pc/4970/" target="_blank" rel="noopener noreferrer">VSCode：ワークスペースでのみ有効な環境変数を設定する - いつかの熊右衛門</a><ul><li>あくまでVSCodeから起動されるシェルのみに有効なのでsourceFileMapとかには使えなかった</li></ul></li><li><a href="https://code.visualstudio.com/docs/editor/variables-reference" target="_blank" rel="noopener noreferrer">Visual Studio Code Variables Reference</a></li></ul><h2 id="カスタムコマンド実行系" tabindex="-1"><a class="header-anchor" href="#カスタムコマンド実行系"><span>カスタムコマンド実行系</span></a></h2><p>C-Shift-p でOpen Keyboard Shortcut(JSON)を選び、以下を書いている。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">{</span>
<span class="line">        &quot;key&quot;: &quot;cmd+e&quot;,</span>
<span class="line">        &quot;command&quot;: &quot;workbench.action.terminal.sendSequence&quot;,</span>
<span class="line">        &quot;args&quot;: {</span>
<span class="line">            &quot;text&quot; : &quot;extract_wikilink.sh &#39;\${file}&#39;\\u000D&quot;</span>
<span class="line">        }</span>
<span class="line">    },{</span>
<span class="line">        &quot;key&quot;: &quot;cmd+t&quot;,</span>
<span class="line">        &quot;command&quot;: &quot;workbench.action.terminal.sendSequence&quot;,</span>
<span class="line">        &quot;args&quot;: {</span>
<span class="line">            &quot;text&quot; : &quot;today.command\\u000D&quot;</span>
<span class="line">        }</span>
<span class="line">    }</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="lldbかえってこない問題" tabindex="-1"><a class="header-anchor" href="#lldbかえってこない問題"><span>lldbかえってこない問題</span></a></h2><p>定期的に発生して毎回解決出来ないが、試す事を一応メモしておく。</p><p>configurationに以下を追加</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">				&quot;logging&quot;: {</span>
<span class="line">						&quot;engineLogging&quot;: true,</span>
<span class="line">						&quot;trace&quot;: true,</span>
<span class="line">						&quot;traceResponse&quot;: true</span>
<span class="line">				},</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>デバッグコンソールでlldbのログが出るようになる。</p><p>以下で帰ってこなくなる。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;-1050-var-create - - &quot;builder&quot; --thread 1 --frame 0</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>以下を削除</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">~/Library/Application Support/Code/Cache</span>
<span class="line">~/Library/Application Support/Code/CachedData</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="codelldb使ってmacでprintfが出力されない" tabindex="-1"><a class="header-anchor" href="#codelldb使ってmacでprintfが出力されない"><span>CodeLLDB使ってMacでprintfが出力されない</span></a></h2><p>よくわからないが、temrinalがintegratedだとダメな事がある。以下にすればとりあえずは出る。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">            &quot;terminal&quot;:&quot;console&quot;,</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="qtのヘッダのincludeパスをインテリセンスなどで効くようにする" tabindex="-1"><a class="header-anchor" href="#qtのヘッダのincludeパスをインテリセンスなどで効くようにする"><span>Qtのヘッダのincludeパスをインテリセンスなどで効くようにする</span></a></h2><p>.envrcに以下のようなのを書いて</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">export PATH=\${HOME}/Qt/6.10.3/macos/bin:$PATH</span>
<span class="line">export MY_QT_LIB_PATH=\`qmake -query QT_INSTALL_LIBS\`</span>
<span class="line">export MY_QT_INCLUDE_PATH=\`qmake -query QT_INSTALL_HEADERS\`</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>c_cpp_properties.jsonに以下のように書く。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">            &quot;includePath&quot;: [</span>
<span class="line">                &quot;\${workspaceFolder}/**&quot;,</span>
<span class="line">                &quot;\${env:MY_QT_INCLUDE_PATH}&quot;,</span>
<span class="line">                &quot;\${env:MY_QT_LIB_PATH}/QtCore.framework/Headers&quot;,</span>
<span class="line">                &quot;\${env:MY_QT_LIB_PATH}/QtGui.framework/Headers&quot;,</span>
<span class="line">                &quot;\${env:MY_QT_LIB_PATH}/QtWidgets.framework/Headers&quot;,</span>
<span class="line">                &quot;\${vcpkgRoot}/arm64-osx/include&quot;,</span>
<span class="line">                &quot;\${vcpkgRoot}/arm64-osx-dynamic/include&quot;</span>
<span class="line">            ],</span>
<span class="line">            &quot;macFrameworkPath&quot;: [</span>
<span class="line">                &quot;/System/Library/Frameworks&quot;,</span>
<span class="line">                &quot;/Library/Frameworks&quot;,</span>
<span class="line">                &quot;\${env:MY_QT_LIB_PATH}&quot;                </span>
<span class="line">            ],</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="gemma-4をagentに使ってみる" tabindex="-1"><a class="header-anchor" href="#gemma-4をagentに使ってみる"><span>Gemma 4をagentに使ってみる</span></a></h2><p>Copilotの無料トークンを使い果たしたのでGemma e2bをagentに使ってみる。</p><p><a href="https://sagnikbhattacharya.com/blog/gemma-4-vscode" target="_blank" rel="noopener noreferrer">How to Use Gemma 4 in VS Code: Setup, Extensions, and Coding Workflows</a></p><p>Continueという拡張を入れるらしい。やってみよう。 ollama関連は<a href="./lazyjp.html">lazyjp</a>にあるように以下。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ brew services start ollama</span>
<span class="line">$ ollama run gemma4:e2b</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>で、上のブログに書かれているように設定してドロップダウンから選んだらchatは出来るようになった。 ただCopilotのように頼むと全部やってくれる感じでは無いなぁ（具体的にどのファイルでやりたいかを質問仕返してくる）。</p><p>もうちょっとやる気がある時に実際に作業してみよう。</p><h3 id="e4bを試してみる。" tabindex="-1"><a class="header-anchor" href="#e4bを試してみる。"><span>e4bを試してみる。</span></a></h3><p>ホームルーターを導入してダウンロードが少しマシになったので、e4bも試してみる。</p><p>Continueというのはなんかいまいちだったので、いろいろ試していた所、ollam launch vscodeで起動すると設定なんていらないぜ、 とChatGPTが言ったのでそれで試す。</p><ol><li>ターミナルからollama launch vscodeを実行し、モデルを選び、VSCodeを再起動</li><li>Copilot Chatのモデルの所のドロップダウンからgemma4: e4b(ollama)を選ぶ</li><li>「こんにちは」と打つもresponse fail</li></ol><p>以下のcurlとかはそれっぽい結果を返すので、どうもモデルは動いてそうだが。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">curl http://localhost:11434/api/generate -d &#39;{</span>
<span class="line">  &quot;model&quot;: &quot;gemma4:e4b&quot;,</span>
<span class="line">  &quot;prompt&quot;: &quot;こんにちは&quot;,</span>
<span class="line">  &quot;stream&quot;: false</span>
<span class="line">}&#39;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>qwen3:8bを試してみたらこちらは出来たので、なんか相性の問題があるっぽい。</p><p>ただいろいろ試していたらメモリがいっぱいになって何も操作出来ない感じになってしまった。ちょっと実用には厳しいかなぁ。</p><h3 id="oai-compatible-provider-for-copilotで使ってみる-失敗" tabindex="-1"><a class="header-anchor" href="#oai-compatible-provider-for-copilotで使ってみる-失敗"><span>OAI Compatible Provider for Copilotで使ってみる（失敗）</span></a></h3><p>追記: ollama launch vscodeの方が良さそう</p><p>Continueというのはなんかいまいちな気がしたので以下で言及のあったOAI COmpatible Provider for Copilotを試してみる。 <a href="https://www.reddit.com/r/ollama/comments/1sdom5v/google_gemma4_via_vscode/" target="_blank" rel="noopener noreferrer">Google Gemma4 via VSCode : r/ollama</a></p><p>Cmd+Shift+PでOAICopilot: Open Configuration UIを開くのか。</p><p>Provider ManagementでAdd Providerをして</p><ul><li>Provider ID: 適当（local ollamaとか）</li><li>BaseURL: <code>http://localhost:11434/v1</code></li><li>API Key: ollama（たぶんなんでも良いと思うけど）</li><li>API Model: Ollama</li></ul><p>API ModelはOpen AIにしないとCopilot Chatからは使えない？</p><p>そしてAdd Modelsする。</p><ul><li>Model ID: gemma4:e4b</li></ul><p>「こんにちは」にもreponse failする。駄目そう。</p><p>ollama launch vscodeでちゃんと設定されたもっと公式っぽいのが動くのでそちらの方が良さそう。</p>`,62)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};